import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.DyxC4IQh.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1792170324000}'),r={name:"guide/faq.md"};function d(c,e,l,p,h,n){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="按-f-打不出字母-f-了" tabindex="-1">按 F 打不出字母 f 了 <a class="header-anchor" href="#按-f-打不出字母-f-了" aria-label="Permalink to &quot;按 F 打不出字母 f 了&quot;">​</a></h2><p>hint 模式内 <code>F</code> 是退出键，会吃掉。要连续打 <code>f</code> 的场景（写代码、聊天）不该在 hint 模式里：按 <code>Esc</code> 出来。</p><p>输入法弹出的时候不用担心这件事，VimAct 那时把按键完全交回 IME，<code>f</code> 正常上屏。</p><h2 id="装了、开了服务、按-f-没反应" tabindex="-1">装了、开了服务、按 F 没反应 <a class="header-anchor" href="#装了、开了服务、按-f-没反应" aria-label="Permalink to &quot;装了、开了服务、按 F 没反应&quot;">​</a></h2><p>按这个顺序排查：</p><ol><li>VimAct 主界面状态行是不是 <code>Status: enabled</code>。</li><li>当前 App 有没有被加进<a href="/vimact-site/guide/settings.html">排除列表</a>。</li><li>输入法是不是正弹着。</li><li>ROM 的省电策略有没有把应用冻结，见<a href="/vimact-site/guide/accessibility.html">各家 ROM 的额外坑</a>。</li></ol><p>四条都排除了还没反应，属于 OEM 的 <code>onKeyEvent</code> 兼容性问题。这是 v0.1 明确的风险项，把机型和 ROM 版本记下来。</p><h2 id="有些控件没有标签" tabindex="-1">有些控件没有标签 <a class="header-anchor" href="#有些控件没有标签" aria-label="Permalink to &quot;有些控件没有标签&quot;">​</a></h2><p>三种原因。</p><p>自绘控件：游戏画面、<code>SurfaceView</code>、部分图表，开发者没暴露无障碍节点，谁都看不见它。</p><p>超出上限：一屏最多标 400 个目标，按阅读顺序取，后面的不标。</p><p>WebView：按浏览器暴露给无障碍树的网页结构处理，长页面或自定义滚动容器会打折。</p><h2 id="标签为什么突然整套变了" tabindex="-1">标签为什么突然整套变了 <a class="header-anchor" href="#标签为什么突然整套变了" aria-label="Permalink to &quot;标签为什么突然整套变了&quot;">​</a></h2><p>为了保持「没有任何标签是另一个标签的前缀」，重排有时候比局部修补更省事，此时整套重新分配一次。表现是滚动一下屏幕，所有标签集体变一次。</p><h2 id="和-key-mapper-会不会打架" tabindex="-1">和 Key Mapper 会不会打架 <a class="header-anchor" href="#和-key-mapper-会不会打架" aria-label="Permalink to &quot;和 Key Mapper 会不会打架&quot;">​</a></h2><p>非 hint 模式下 VimAct 不消费按键——除开方向键、通知键、触发键这几个它确实在用的，其余一律放行。这求的是共存，不是集成。</p><p>需要留意的是键位撞车：如果 Key Mapper 也把 <code>F</code> 或 <code>Space</code> 映射了别的动作，两边都会想拦。建议把 VimAct 的通知键或光标点击键（见设置）挪开，或者在 Key Mapper 侧避开这几个键。</p><h2 id="会不会读到我的密码" tabindex="-1">会不会读到我的密码 <a class="header-anchor" href="#会不会读到我的密码" aria-label="Permalink to &quot;会不会读到我的密码&quot;">​</a></h2><p>无障碍服务能读到的东西由系统决定：节点类名、<code>viewId</code>、文本、<code>contentDescription</code>、边界坐标。它拿不到屏幕像素，那需要录屏权限，VimAct 没申请。</p><p>密码类输入框在系统层默认不会把明文文本回传给无障碍节点。而且输入框一旦激活、输入法弹出，VimAct 立刻收起全部标签和光标，完全不碰按键。</p><p>至于读取范围本身：APK 没有 <code>INTERNET</code> 权限，装机的权限清单上可以直接看到。数据没有出口。</p><h2 id="费电吗" tabindex="-1">费电吗 <a class="header-anchor" href="#费电吗" aria-label="Permalink to &quot;费电吗&quot;">​</a></h2><p>那个 32 毫秒的重扫循环只在两种情况下跑：hint 模式开着，或者光标还活着。空闲时只处理系统的窗口变化事件，并且做了 16 毫秒节流。</p><p>通知角标每 140 毫秒淡入淡出一次，跟手。</p><h2 id="需要-root-或者跑-adb-命令吗" tabindex="-1">需要 root 或者跑 ADB 命令吗 <a class="header-anchor" href="#需要-root-或者跑-adb-命令吗" aria-label="Permalink to &quot;需要 root 或者跑 ADB 命令吗&quot;">​</a></h2><p>都不需要。第一次设置只有安装 APK 和打开无障碍服务开关两步。网上有些同类工具的教程要求你常驻 <code>adb shell</code> 或执行 <code>input tap</code>，VimAct 走的是 <code>dispatchGesture</code>，那条路不需要 shell。</p><h2 id="分屏、画中画、折叠屏外屏" tabindex="-1">分屏、画中画、折叠屏外屏 <a class="header-anchor" href="#分屏、画中画、折叠屏外屏" aria-label="Permalink to &quot;分屏、画中画、折叠屏外屏&quot;">​</a></h2><p>折叠屏和平板的物理键盘场景是主要目标之一，常规使用没问题。分屏、多窗口、画中画下只依赖活动窗口的根节点，行为不做保证。</p><h2 id="源码在哪能看到" tabindex="-1">源码在哪能看到 <a class="header-anchor" href="#源码在哪能看到" aria-label="Permalink to &quot;源码在哪能看到&quot;">​</a></h2><p>目前不开源，页面上也没有 GitHub 按钮。首个正式版发布时一并说明源码计划。</p>',31)])])}const f=a(r,[["render",d]]);export{u as __pageData,f as default};
